            // Operand 2
            // 'exist' Association operator
            SQLWhereOperandSubQuery operandSubQueryAssocOperator074 = new SQLWhereOperandSubQuery(repository.assocOperator074Range1Query(vTipoDoc, vNumDoc, sql));
